/* Winter Arc: no network calls, accounts, analytics or build dependencies. */
'use strict';
const C=WA_CORE,D=WA_DATA,TEST=new URLSearchParams(location.search).has('sandbox'),SANDBOX=(new URLSearchParams(location.search).get('sandbox')||'1').replace(/[^a-z0-9-]/gi,'').slice(0,30),KEY='winter-arc-v1'+(TEST?'-sandbox'+(SANDBOX==='1'?'':'-'+SANDBOX):''),TIMER_KEY='winter-arc-timer-v1'+(TEST?'-sandbox'+(SANDBOX==='1'?'':'-'+SANDBOX):'');
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const clone=x=>JSON.parse(JSON.stringify(x));
const navItems=[['basecamp','⌂','Basecamp'],['syllabus','◈','Study map'],['roadmap','≋','The roadmap'],['life','ϟ','Life & weekly goals'],['focus','◷','Focus chamber'],['mocks','▥','Mock lab'],['rewards','◇','Rewards & ranks'],['guide','▤','Field guide'],['settings','⚙','Settings']];
const statusNames={'not-started':'Not started',learning:'Learning',practice:'Practising',revision:'Revising',mastered:'Mastered'};
const X=WA_CUSTOM,disk=WA_DISK;
function subjects(){return state.settings.subjects||D.subjects;}
function examList(){return state.settings.exams||[{name:'JEE',date:state.settings.jeeDate,maxScore:300},{name:'CLAT',date:state.settings.clatDate,maxScore:120},{name:'AILET',date:state.settings.ailetDate,maxScore:150}];}
function examScales(){return Object.fromEntries(examList().map(e=>[e.name,e.maxScore]));}
function companion(){return X.companionForm(state.settings.companion,C.level(C.totalXP(state)));}
let fileFailed=false,newUser=true,memoryDirty=false;

function fresh(){return {version:1,revision:0,settings:{name:'Explorer',hours:8,dailyGoal:300,theme:'dark',motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,sound:false,timerSound:true,jeeDate:'2027-01-20',clatDate:'2026-12-06',ailetDate:'2026-12-13',jeeConfirmed:false,notes:'Choose your subjects, build useful practice, and review your mistakes.'},chapters:clone(D.chapters),weeks:clone(D.weeks),quests:[],workouts:[],weeklyGoals:[],sessions:[],mocks:[],errors:[],ledger:[],rewards:clone(D.rewards),redemptions:[],badges:[],guideEdits:{}};}
let state=fresh(),storageOK=true,stale=false,loadError=false,page=navItems.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'basecamp',subjectFilter='All',statusFilter='all',search='',mockFilter='JEE',timer=null,toastHandle,focusDraft={subject:subjects()[0],chapterId:'',minutes:25},lastDay=C.day();
try{const raw=localStorage.getItem(KEY);if(raw){newUser=false;state=C.validate(JSON.parse(raw));state.revision=Number.isSafeInteger(state.revision)?state.revision:0;}localStorage.setItem('wa-storage-check','ok');localStorage.removeItem('wa-storage-check');}catch(e){storageOK=false;loadError=true;}
try{const t=JSON.parse(localStorage.getItem(TIMER_KEY)||'null');if(t&&subjects().includes(t.subject)&&Number.isInteger(t.minutes)&&t.minutes>=1&&t.minutes<=1440&&Number.isFinite(t.elapsed)&&t.elapsed>=0){timer={...t,elapsed:Math.min(t.elapsed,t.minutes*60000),running:false,since:null};}}catch{}
function warning(message){let el=$('#storage-warning');if(!el){el=document.createElement('div');el.id='storage-warning';el.setAttribute('role','alert');document.body.append(el);}el.textContent=message;}
function persist(){if(state.settings.storageMode==='file'&&!disk.handle){checkEditable();memoryDirty=true;$('#save-status').textContent='Unsaved — create or open a planner file';warning('Your workspace is in memory. Create a planner file in Settings to save it on your device.');return;}if(disk.handle){checkEditable();state.revision=(state.revision||0)+1;saveToDisk();return;}if(stale)throw Error('Another tab changed your progress. Reload this tab before editing.');if(loadError)throw Error('Stored data could not be read safely. Export recovery data or restore a backup in Settings.');try{state.revision=(state.revision||0)+1;localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-status').textContent='Saved on this browser';}catch(e){storageOK=false;$('#save-status').textContent='Not saved — export a backup';warning('Browser storage is unavailable or full. Keep this tab open and export a backup now.');throw e;}}
function saveTimer(){if(state.settings.storageMode==='file'&&!disk.handle)return;if(disk.handle){if(!fileFailed&&!stale)saveToDisk();return;}try{if(timer)localStorage.setItem(TIMER_KEY,JSON.stringify({...timer,elapsed:timerElapsed(),running:false,since:null}));else localStorage.removeItem(TIMER_KEY);}catch{toast('Timer could not be saved. Keep this tab open.');}}
function toast(message){clearTimeout(toastHandle);$('#toast').textContent=message;$('#toast').classList.add('show');toastHandle=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function closeModal(){$('#modal').close();}
function modal(title,body,onSubmit){$('#modal-content').innerHTML=`<div class="dialog-heading"><h2 id="modal-title">${esc(title)}</h2><button type="button" data-action="close" aria-label="Close dialog">×</button></div><form id="dialog-form"><div class="validation" role="alert"></div>${body}</form>`;$('#modal').showModal();$('#dialog-form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.currentTarget));}catch(err){$('#dialog-form .validation').textContent=err.message||'Could not save. Try again.';}};}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'inputmode="decimal"':''} ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label class="field">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function select(label,name,items,value,extra=''){return `<label class="field">${label}<select name="${name}" ${extra}>${items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function actions(text='Save changes'){return `<div class="dialog-actions"><button type="button" class="quiet" data-action="close">Cancel</button><button class="primary" type="submit">${text}</button></div>`;}
function dateLabel(d){return C.validDate(d)?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'—';}
function assert(ok,message){if(!ok)throw Error(message);}
function checkEditable(){if(fileFailed)throw Error('File save failed. Export your unsaved work, then reopen the file.');assert(!stale,'Another tab changed progress. Reload to sync before editing.');assert(!loadError,'Restore a valid backup before editing; existing unreadable data is being preserved.');}
function changed(message,beforeXP=C.totalXP(state)){checkEditable();const newBadges=C.unlock(state);try{persist();}catch(e){toast(e.message);return;}closeModal();render();const newLevel=C.level(C.totalXP(state));if(newLevel>C.level(beforeXP))celebrate(newLevel,newBadges,X.evolutionLevels.slice(1).some(at=>newLevel>=at&&C.level(beforeXP)<at));else toast(newBadges.length?`${newBadges[0].name} unlocked! ${message}`:message);}
function celebrate(l,badges=[],evolved=false){$('#celebration').innerHTML=`<div class="eyebrow">A LITTLE STRONGER THAN YESTERDAY</div>${evolved?`<div class="evolution-art stage-${companion().tier}" style="--companion-color:${companion().color}"><img class="evolution-reveal" src="assets/${companion().asset}" alt="${esc(companion().name)}"></div><p class="ice">${esc(companion().name)} evolved · ${esc(companion().form)}</p>`:'<div class="burst" aria-hidden="true">❄</div>'}<h2 id="celebration-title">Level ${l}</h2><h3>${esc(C.rank(l))}</h3><p>${badges.length?esc(badges.map(b=>b.name).join(' · ')):'Earned through showing up and doing the work.'}</p><button class="primary" data-action="celebration-close">Keep climbing</button>`;$('#celebration').showModal();chime();}
let audioContext;
async function prepareAudio(){try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();return audioContext.state==='running';}catch{return false;}}
async function chime(completion=false){if(completion?state.settings.timerSound===false:!state.settings.sound)return;if(!await prepareAudio()){toast('Sound could not play. Unmute this tab and try Test chime.');return;}const a=audioContext;[523.25,659.25,783.99,1046.5].forEach((f,i)=>{const o=a.createOscillator(),g=a.createGain(),start=a.currentTime+i*.16;o.type='sine';o.frequency.value=f;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.12,start+.015);g.gain.exponentialRampToValueAtTime(.001,start+.65);o.start(start);o.stop(start+.7);o.onended=()=>{o.disconnect();g.disconnect();};});}

function go(next){closeModal();if(next!=='focus')document.body.classList.remove('focus-only');page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function heading(title,description,button=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${button}</div>`;}
function studyDuration(minutes){return minutes<60?minutes+' min':Math.floor(minutes/60)+' h '+String(minutes%60).padStart(2,'0')+' min';}
function stat(label,value,foot,icon=''){return `<div class="card stat"><div class="stat-label">${label}<span aria-hidden="true">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function empty(title,detail,button=''){return `<div class="empty"><strong>${title}</strong><p>${detail}</p>${button}</div>`;}
function button(action,label,id='',cls='small quiet'){return `<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;}
function progress(subject){const cs=state.chapters.filter(c=>c.subject===subject),done=cs.filter(c=>c.status==='mastered').length;return `<div class="subject-progress"><div class="row"><span><i class="subject-dot ${esc(subject)}"></i>${esc(subject)}</span><small>${done} / ${cs.length} mastered</small></div><div class="track" role="progressbar" aria-label="${esc(subject)} mastery" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${cs.length}"><span style="width:${cs.length?done/cs.length*100:0}%"></span></div></div>`;}
function countdown(name,date,provisional=false){const d=C.daysUntil(date);return `<div class="countdown"><p class="exam-name">${name}</p><strong>${d>0?d:d===0?'Today':'Passed'}${d>0?'<small>days left</small>':''}</strong><p>${dateLabel(date)} ${date.slice(0,4)}</p>${provisional?'<div class="provisional">PLANNING DATE</div>':''}</div>`;}
function timeSplit(){if(state.settings.exams)return `${state.settings.hours} h across your subjects`;const h=state.settings.hours,cl=C.daysUntil(state.settings.clatDate),ai=C.daysUntil(state.settings.ailetDate);let jee=ai<0?h:cl<0?Math.min(2,h):cl<=7?Math.min(1.5,h):cl<=20?h/2:Math.max(1,h*.75-.5);jee=Math.round(jee*4)/4;return `${jee} h JEE · ${Math.round((h-jee)*4)/4} h law`;}
function currentWeek(){return state.weeks.find(w=>w.start<=C.day()&&w.end>=C.day());}
function suggestQuests(){checkEditable();if(state.quests.some(q=>q.date===C.day())){toast('Today already has an expedition. Edit it or add a block.');return;}for(const subject of subjects()){const due=state.chapters.find(c=>c.subject===subject&&c.nextReview&&c.nextReview<=C.day());const chapter=due||state.chapters.find(c=>c.subject===subject&&c.status!=='mastered');state.quests.push({id:uid(),title:chapter?`${chapter.name} · ${due?'revision':'independent practice'}`:`${esc(subject)} · mixed practice`,subject,date:C.day(),minutes:subject==='Law'?40:50,done:false});}changed(`${subjects().length} blocks planned. Adjust them to the work you actually need.`);}
function questHTML(q){return `<div class="quest ${q.done?'done':''}"><button class="check" data-action="quest-toggle" data-id="${q.id}" aria-label="${q.done?'Reopen':'Complete'} ${esc(q.title)}" aria-pressed="${q.done}">${q.done?'✓':''}</button><div class="quest-text"><h3>${esc(q.title)}</h3><p><i class="subject-dot ${esc(q.subject)}"></i>${esc(q.subject)} · ${q.minutes} min${q.date<C.day()?' · carried over from '+dateLabel(q.date):''}</p></div><span class="xp-pill">${q.done?'DONE':'+10 XP'}</span>${button('quest-edit','⋯',q.id)}</div>`;}
function home(){const xp=C.totalXP(state),l=C.level(xp),today=C.day(),minutes=C.focusMinutes(state,today),qs=state.quests.filter(q=>q.date===today||q.date<today&&!q.done),jee=state.chapters,mastered=jee.filter(c=>c.status==='mastered').length,w=currentWeek(),due=state.chapters.filter(c=>c.nextReview&&c.nextReview<=today);return `${heading(`Your winter, ${esc(state.settings.name)}.`, `Today’s suggested rhythm: ${timeSplit()}. Mocks replace normal blocks.`,button('start-focus','◷ &nbsp; Start focus','','primary'))}
<section class="banner has-art"><div><span class="eyebrow">THE COMEBACK SEASON</span><h1 id="daily-quote">${esc(X.dailyQuote(today))}</h1><p>${esc(examList().map(e=>e.name).join(' · ')||'Your subjects. Your season.')}<br>One honest session. One less unfamiliar question.</p><div class="banner-tags"><span class="tag">❄ Winter Arc · Season 01</span><span class="tag">${w?esc(w.title):'Your own pace. Your next step.'}</span></div></div></section>
<div class="stats-grid study-stats">${stat('Studied today',studyDuration(minutes),`${minutes} / ${state.settings.dailyGoal} min · ${minutes>=state.settings.dailyGoal?'Target reached':Math.max(0,state.settings.dailyGoal-minutes)+' min to target'}`,'◷')}${stat('Lifetime study time',studyDuration(C.focusMinutes(state)),`${state.sessions.length} logged ${state.sessions.length===1?'session':'sessions'} · Every honest minute counts`,'∞')}${stat('Study streak',`${C.streak(state)}<small>days</small>`,'25 focused minutes keeps the trail alive','ϟ')}${stat('Topics mastered',`${mastered}<small>/ ${jee.length}</small>`,'Two strong checks. Real progress.','◈')}${stat('Frost crystals',`<span class="ice">${C.crystals(state)}</span>`,'Small rewards, earned through effort','◇')}</div>
<div class="two-col"><section class="card"><div class="section-head"><h2>Today’s expedition</h2><div class="row-actions">${button('suggest','Suggest blocks')}${button('quest-new','+ Add')}</div></div>${qs.length?`<div class="quests">${qs.map(questHTML).join('')}</div><p class="helper">Finish the actual work before checking it off. First three completions today earn XP.</p>`:empty('Pick your next few moves.','Start with four focused blocks from your study map. You can change every one.',button('suggest','Build today’s expedition','','primary'))}</section>
<section class="card companion"><div class="section-head"><span class="eyebrow">YOUR COMPANION</span><span class="tag">LVL ${l}</span></div><div class="companion-stage evolution-${companion().tier}" style="--companion-color:${companion().color}"><div class="evolution-art stage-${companion().tier}"><img decoding="async" class="pet ${companion().asset.endsWith('.svg')?'pixel-pet':''}" src="assets/${companion().asset}" alt="${esc(companion().name+' · '+companion().detail)}"></div></div><h3>${esc(companion().name)} · ${esc(companion().form)}</h3><p class="evolution-caption">${companion().next?'Next evolution at level '+companion().next:'Final evolution unlocked'}</p>${button('companions','Choose companion')}${button('companion-evolution','Evolution path','','quiet small')}<p>${minutes>=25?'You showed up. That counts.':'I’ll keep you company. You bring the effort.'}</p><div class="xp-track" role="progressbar" aria-label="Progress to level ${l+1}" aria-valuemin="${C.threshold(l)}" aria-valuemax="${C.threshold(l+1)}" aria-valuenow="${xp}"><span style="width:${(xp-C.threshold(l))/(C.threshold(l+1)-C.threshold(l))*100}%"></span></div><div class="progress-label"><span>${xp} XP</span><span>${C.threshold(l+1)-xp} to level ${l+1}</span></div></section></div>
<div class="two-col"><section class="card"><div class="section-head"><h2>The next summits</h2>${button('settings','Edit dates')}</div><div class="countdown-grid">${examList().map(e=>countdown(e.name,e.date,!state.settings.exams&&e.name==='JEE'&&!state.settings.jeeConfirmed)).join('')||'<p class="muted">Add exam dates in Settings.</p>'}</div><p class="helper">Dates are planning targets. Confirm them from your official timetable.</p></section><section class="card"><div class="section-head"><h2>Your study map</h2>${button('syllabus','Explore')}</div>${subjects().map(progress).join('')}</section></div>
<div class="two-col"><section class="card"><div class="section-head"><h2>Keep it from fading</h2><span class="muted">${due.length} chapter reviews due</span></div>${due.length?due.slice(0,4).map(c=>`<div class="session-row"><div>${esc(c.name)}<small>${esc(c.subject)} · due ${dateLabel(c.nextReview)}</small></div>${button('chapter','Review',c.id)}</div>`):'<p class="muted tiny">Log a chapter check and set its next review. Your revision queue will appear here.</p>'}${state.errors.filter(e=>e.nextReview<=today).length?`<p class="helper">${state.errors.filter(e=>e.nextReview<=today).length} error-log repairs also due. ${button('mocks','Open Mock lab')}</p>`:''}</section><section class="card"><h2>The last 14 days</h2><div class="activity-strip">${Array.from({length:14},(_,i)=>{const date=C.addDays(today,i-13),m=C.focusMinutes(state,date);return `<div class="activity-day ${m>=25?'active':''}" title="${date}: ${m} focus minutes" aria-label="${date}: ${m} minutes"></div>`;}).join('')}</div><p class="helper">${state.sessions.filter(s=>s.date>=C.addDays(today,-13)).reduce((n,s)=>n+s.minutes,0)} minutes logged. A quiet day doesn’t erase your progress.</p><div class="quote">“Your next level is earned off-screen.”</div></section></div>`;}
function syllabus(){const cs=state.chapters.filter(c=>(subjectFilter==='All'||c.subject===subjectFilter)&&(statusFilter==='all'||c.status===statusFilter)&&`${c.name} ${c.notes}`.toLowerCase().includes(search.toLowerCase()));return `${heading('The study map','Your syllabus, your subjects. Move from familiar to usable.',`<div class="row-actions">${button('syllabus-upload','Import syllabus')}${button('chapter-new','+ Add chapter','','primary')}</div>`)}<div class="tabs" aria-label="Filter subject">${['All',...subjects()].map(s=>`<button data-subject="${esc(s)}" class="${subjectFilter===s?'selected':''}" aria-pressed="${subjectFilter===s}">${esc(s)}</button>`).join('')}</div><div class="toolbar"><input id="chapter-search" aria-label="Search chapters" placeholder="Find a chapter or a concept…" value="${esc(search)}"><select id="status-filter" aria-label="Filter chapter status" style="width:auto"><option value="all">Every stage</option>${Object.entries(statusNames).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}</select><span id="chapter-count" class="muted tiny">${cs.length} topics</span></div><div class="notice">Mastery needs two recent checks of at least 10 questions, each at 75%+. The list is your selected plan—not the complete official syllabus.</div><div id="chapter-results"><div class="chapter-grid">${cs.map(c=>`<article class="card chapter"><div class="section-head"><span class="eyebrow"><i class="subject-dot ${esc(c.subject)}"></i>${esc(c.subject)}</span><span class="status ${c.status}">${statusNames[c.status]}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.prerequisite)}</p><div class="chapter-bottom"><span class="tiny muted">${esc(c.priority)}${c.checks.length?' · '+Math.round(c.checks.at(-1).correct/c.checks.at(-1).total*100)+'% last check':''}</span>${button('chapter','Open',c.id)}</div></article>`).join('')}</div>${!cs.length?empty('No topics here.','Try another filter or add a chapter.'):''}</div>`;}
function roadmap(){return `${heading('A season with a direction','A flexible route through your study season. Edit as you learn.',button('week-new','+ Add week','','primary'))}<div class="notice">Weeks are focus areas, not compulsory completions. Keep one major backlog per subject at most.</div><div class="roadmap">${[...state.weeks].sort((a,b)=>a.start.localeCompare(b.start)).map((w,i)=>`<article class="card week ${w.start<=C.day()&&w.end>=C.day()?'current':''}"><div class="week-time"><span class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')}</span><strong>${dateLabel(w.start)} – ${dateLabel(w.end)}</strong><small>${esc(w.title)}</small>${w.start<=C.day()&&w.end>=C.day()?'<p class="ice tiny">YOU ARE HERE</p>':''}</div><div class="week-content">${w.blocks?Object.entries(w.blocks).map(([subject,v])=>`<div><b>${esc(subject)}</b><p>${esc(v)}</p></div>`).join(''):[['Physics',w.physics],['Chemistry',w.chemistry],['Maths',w.maths]].map(([subject,v])=>`<div><b>${esc(subject)}</b><p>${esc(v)}</p></div>`).join('')}<div class="week-note">${esc(w.note)}</div></div>${button('week-edit','Edit',w.id)}</article>`).join('')}</div>`;}
function sessionHTML(s){return `<div class="session-row"><div><span class="subject-dot ${s.subject}"></span>${s.subject}<small>${dateLabel(s.date)} · ${esc(s.note||'Focused study')}</small></div><strong>${s.minutes}<small>minutes</small></strong></div>`;}
function focus(){const t=timer||focusDraft,cs=state.chapters.filter(c=>c.subject===t.subject);return `${heading('Focus chamber','One task. One session. Everything else can wait.',button('zen',document.body.classList.contains('focus-only')?'Exit quiet mode':'Enter quiet mode'))}<div class="study-totals">${stat('Studied today',studyDuration(C.focusMinutes(state,C.day())),'Completed and logged study','◷')}${stat('Lifetime study time',studyDuration(C.focusMinutes(state)),'Timer sessions and offline study logs','∞')}</div><div class="focus-layout"><section class="card focus-card ${timer?'running':''}"><span class="eyebrow" id="focus-state">${timer?(remaining()<=0?'SESSION COMPLETE · WELL DONE':timer.running?'IN THE ZONE':'PAUSED · BREATHE, THEN RETURN'):'MAKE ROOM FOR THE WORK'}</span><div class="focus-clock" id="focus-clock">${clockText(timer?remaining():t.minutes*60000)}</div><p class="focus-caption" id="focus-caption">${timer?esc(timer.subject+' · '+(state.chapters.find(c=>c.id===timer.chapterId)?.name||'Focused study')):'Put your phone away. Open your questions.'}</p><div class="focus-controls">${timer?`${remaining()>0?button('timer-toggle',timer.running?'Pause':'Resume','','primary'):''}${button('timer-finish','Finish & log')}${button('timer-discard','Discard')}`:button('timer-start','Begin session','','primary')}</div><div class="focus-config">${select('Subject','focus-subject',subjects(),t.subject)}${select('Session length','focus-minutes',[[25,'25 minutes'],[30,'30 minutes'],[35,'35 minutes'],[40,'40 minutes'],[50,'50 minutes'],[90,'90 minutes'],['custom','Custom duration']],focusDraft.custom?'custom':t.minutes)}${focusDraft.custom?field('Custom minutes (1–1440)','focus-custom',t.minutes,'number','min="1" max="1440" step="1" required'):''}<div class="span-two">${select('Chapter or skill','focus-chapter',[['','Mixed practice / revision'],...cs.map(c=>[c.id,c.name])],t.chapterId)}</div></div><div class="row-actions"><label class="check-label"><input type="checkbox" name="timer-sound" ${state.settings.timerSound!==false?'checked':''}>Completion chime</label>${button('timer-test-sound','Test chime')}</div><p class="helper">Keep this page open and unmuted. Phone lock or backgrounding can silence the chime; the timer catches up when you return.</p><p class="helper">1 XP per active minute · minimum 10 minutes · 360 focus XP daily cap.<br>Pause for interruptions. Confirm actual study time when you finish.</p></section><section class="card"><div class="section-head"><h2>Your recent sessions</h2>${button('session-new','+ Log offline')}</div>${state.sessions.length?state.sessions.slice(-6).reverse().map(sessionHTML).join(''):empty('Your first footprint awaits.','Start the timer, or log work you completed away from the screen.')}<div class="quote">Suggested rhythm: 25–50 minutes of focus, then a normal break. Longer sessions are optional.</div></section></div>`;}
function chartHTML(ms,max){const list=ms.slice(-10);if(!list.length)return empty('Your trend starts with one paper.','Record a real mock. No sample scores are added to your history.');const lo=Math.min(0,...list.map(m=>m.score)),range=max-lo,x=i=>list.length===1?300:45+i*(510/(list.length-1)),y=v=>140-(v-lo)/range*110;return `<svg class="chart" viewBox="0 0 600 175" role="img" aria-label="${esc(mockFilter)} mock score trend, chronological. Exact scores appear in the table below.">${[0,max/2,max].map(v=>`<line x1="40" y1="${y(v)}" x2="575" y2="${y(v)}"/><text x="3" y="${y(v)+4}">${v}</text>`).join('')}<polyline points="${list.map((m,i)=>`${x(i)},${y(m.score)}`).join(' ')}" fill="none" stroke="var(--ice)" stroke-width="2.5"/>${list.map((m,i)=>`<circle cx="${x(i)}" cy="${y(m.score)}" r="4" fill="var(--ice)"/><text x="${x(i)}" y="165" text-anchor="middle">${dateLabel(m.date)}</text>`).join('')}</svg>`;}
function mocks(){if(!examList().length)return `${heading('The mock lab','Add an exam and its score scale to start.',button('workspace','Set up exams','','primary'))}`;const ms=state.mocks.filter(m=>m.exam===mockFilter).sort((a,b)=>a.date.localeCompare(b.date)),avg=C.average(ms.slice(-3).map(m=>m.score)),previous=C.average(ms.slice(-6,-3).map(m=>m.score)),delta=avg!==null&&previous!==null?avg-previous:null;return `${heading('The mock lab','Turn a paper into a better next attempt.',button('mock-new','+ Record a mock','','primary'))}<div class="tabs">${Object.keys(examScales()).map(e=>`<button data-exam="${esc(e)}" class="${mockFilter===e?'selected':''}">${esc(e)} <span class="muted">/ ${examScales()[e]}</span></button>`).join('')}</div><div class="three-col mb">${stat('Last 3 average',avg===null?'—':avg.toFixed(1),`Out of ${examScales()[mockFilter]} · ${Math.min(3,ms.length)} recorded papers`)}${stat('Change vs previous 3',delta===null?'—':(delta>=0?'+':'')+delta.toFixed(1),'Compare papers of similar difficulty')}${stat('Analysis complete',`${ms.filter(m=>m.analysed).length}<small>/ ${ms.length}</small>`,'A mock is useful when you repair it')}</div><section class="card mb"><div class="section-head"><h2>${esc(mockFilter)} · your trajectory</h2><span class="muted tiny">Last 10 papers</span></div>${chartHTML(ms,examScales()[mockFilter])}</section>${ms.length?`<section class="card mb table-wrap"><table><thead><tr><th>Paper</th><th>Date</th><th>Score</th><th>Time</th><th>Review</th><th></th></tr></thead><tbody>${[...ms].reverse().map(m=>`<tr><td data-label="Paper">${esc(m.name)}${m.exam==='JEE'&&m.scores.some(x=>x!==null)?`<div class="tiny muted">P ${m.scores[0]??'—'} · C ${m.scores[1]??'—'} · M ${m.scores[2]??'—'}</div>`:''}</td><td data-label="Date">${dateLabel(m.date)}</td><td data-label="Score"><strong>${m.score}</strong> / ${examScales()[m.exam]}</td><td data-label="Time">${m.minutes}m</td><td data-label="Review"><span class="status ${m.analysed?'mastered':'practice'}">${m.analysed?'Analysed':'Needs analysis'}</span></td><td>${button('mock-edit','Open',m.id)}</td></tr>`).join('')}</tbody></table></section>`:''}<section class="card"><div class="section-head"><div><h2>Repair queue</h2><p class="helper">Specific fixes. Spaced reattempts. Fewer repeated mistakes.</p></div>${button('error-new','+ Add mistake')}</div>${state.errors.length?[...state.errors].sort((a,b)=>a.nextReview.localeCompare(b.nextReview)).map(e=>`<article class="error-card"><div><h3>${esc(e.topic)} <span class="status">${esc(e.cause)}</span></h3><p>${esc(e.repair)}</p><small>${esc(e.subject)} · ${e.nextReview<=C.day()?'Due now':'Next '+dateLabel(e.nextReview)} · ${e.reviews.length} reattempts</small></div><div class="row-actions">${button('error-edit','Edit',e.id)}${e.nextReview<=C.day()?button('error-review','Reattempted',e.id,'small primary'):''}</div></article>`).join(''):empty('Keep the useful mistakes.','Add the concept you missed and an action that could fix it.')}</section>`;}
function rewards(){const xp=C.totalXP(state),l=C.level(xp),balance=C.crystals(state);return `${heading('Earn the little extras','A reason to show up. Never a reason to skip rest.',button('reward-new','+ Custom reward','','primary'))}<div class="three-col mb">${stat('Frost crystals',`<span class="ice">${balance}</span>`,'1 crystal per 10 lifetime XP','◇')}${stat('Current rank',`Level ${l}`,esc(C.rank(l)),'❄')}${stat('Achievements',`${state.badges.length}<small>/ ${C.badges.length}</small>`,'Process over perfection','✧')}</div><div class="notice">Normal meals, sleep and regular breaks are unconditional. Crystals buy optional extras. A 50-minute session earns 5 crystals; rewards take several honest sessions.</div><div class="reward-grid">${state.rewards.map(r=>`<article class="card reward"><div class="section-head"><span class="reward-icon">${esc(r.icon)}</span>${button('reward-edit','Edit',r.id)}</div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="row-actions"><span class="ice">◇ ${r.cost}</span><button class="small ${balance>=r.cost?'primary':'quiet'}" data-action="redeem" data-id="${r.id}" ${balance<r.cost?'disabled':''}>${balance>=r.cost?'Redeem':`${r.cost-balance} to go`}</button></div></article>`).join('')}</div><section class="mt"><div class="section-head"><h2>Little milestones. Lasting momentum.</h2></div><div class="achievement-grid">${C.badges.map(b=>`<article class="card achievement ${state.badges.includes(b.id)?'unlocked':''}"><div class="achievement-symbol">${b.icon}</div><div><h3>${b.name}${state.badges.includes(b.id)?' ✓':''}</h3><p>${b.detail}</p></div></article>`).join('')}</div></section><section class="card mt"><h2>Your reward shelf</h2>${state.redemptions.length?state.redemptions.slice().reverse().map(r=>`<div class="session-row"><div>${esc(r.name)}<small>${dateLabel(r.date)} · ${r.cost} crystals${r.used?' · enjoyed':''}</small></div>${r.used?'<span class="status mastered">Enjoyed</span>':button('reward-use','Mark enjoyed',r.id)}</div>`).join(''): '<p class="muted tiny">Redeemed rewards will wait here until you enjoy them.</p>'}</section>`;}
function settings(){const s=state.settings;return `${heading('Make this your basecamp','Small adjustments. Then back to the work.')}<form id="settings-form"><div class="settings-grid"><section class="card"><h2>Your rhythm</h2>${field('Your name','name',s.name,'text','required maxlength="60"')}${field('Available focused hours per day','hours',s.hours,'number','min="2" max="12" step="0.5" required')}${field('Daily focus tracker target (minutes)','dailyGoal',s.dailyGoal,'number','min="25" max="720" step="5" required')}<p class="helper mb">This tracks logged sessions, not every useful minute of your day. Your target never limits XP eligibility.</p>${select('Appearance','theme',[['dark','Midnight snow · dark'],['light','First snowfall · light']],s.theme)}<label class="check-label"><input type="checkbox" name="motion" ${s.motion?'checked':''}>Ambient motion, snow and companion</label><label class="check-label"><input type="checkbox" name="sound" ${s.sound?'checked':''}>Gentle level-up chime</label>${area('Your intention / planning notes','notes',s.notes,'maxlength="20000"')}</section><section class="card"><h2>Your subjects and exams</h2><p class="muted">College semester, entrance exam, certification: name your subjects and score scales.</p><div class="row-actions">${button('workspace','Edit subjects & exams')}${button('syllabus-upload','Import PDF / Word')}${button('bulk-chapters','Paste syllabus')}${button('companions','Choose companion')}${button('tutorial','Replay tutorial')}</div><div class="countdown-grid mt">${examList().map(e=>countdown(e.name,e.date)).join('')}</div><p class="helper mb">Use your confirmed timetable. Existing records are kept when adding subjects or exams.</p><div class="validation" id="settings-error" role="alert"></div><button class="primary wide" type="submit">Save preferences</button></section></div></form>${fileSettings()}<section class="card mt"><h2>Your progress belongs to you</h2><p class="muted">${disk.handle?'Saved to your chosen file on this device.':'Choose a planner file above to save on your device, or keep using browser storage.'} No cloud or account. Keep a second backup of your file.</p><div class="row-actions">${button('export','Export backup','','primary')}${button('import','Restore backup')}${loadError?button('export-raw','Export unreadable recovery data'):''}</div><p class="helper">Restore replaces the current planner after confirmation. Existing data is validated before any replacement. Use one editing tab at a time.</p></section>`;}
function guide(){const holder=document.createElement('div');holder.innerHTML=guideSource();const content=[...holder.querySelectorAll('details')].map((d,i)=>`<details ${i===0?'open':''}><summary>${esc(d.querySelector('summary').textContent)}</summary><div class="row-actions mt">${button('guide-edit','Edit this section',String(i))}</div>${state.guideEdits?.[i]?'<p class="prewrap">'+esc(state.guideEdits[i])+'</p>':[...d.children].filter(x=>x.tagName!=='SUMMARY').map(x=>x.outerHTML).join('')}</details>`).join('');return `${heading('The field guide','Your structured plan, with room to adapt.')}<section class="card prose">${content}</section><section class="card mt"><div class="section-head"><h2>Your own notes</h2>${button('settings','Edit')}</div><p class="prewrap muted">${esc(state.settings.notes)}</p></section>`;}
function applyTheme(){document.documentElement.dataset.theme=state.settings.theme;document.body.classList.toggle('still',!state.settings.motion);$('#theme-toggle').textContent=state.settings.theme==='dark'?'☀':'☾';$('#theme-toggle').setAttribute('aria-label',`Switch to ${state.settings.theme==='dark'?'light':'dark'} mode`);document.dispatchEvent(new Event('wa:theme'));}
function render(){if(!subjects().includes(focusDraft.subject))focusDraft.subject=subjects()[0];if(!Object.hasOwn(examScales(),mockFilter))mockFilter=examList()[0]?.name||'';applyTheme();$('#nav').innerHTML=navItems.map(([id,icon,name])=>`<button class="${id===page?'active':''}" data-page="${id}" aria-label="${name}" ${id===page?'aria-current="page"':''}><span aria-hidden="true">${icon}</span><span class="nav-label">${name}</span><span class="mobile-label" aria-hidden="true">${({basecamp:'Home',syllabus:'Study',focus:'Focus',life:'Life'})[id]||name}</span></button>`).join('')+`<button class="mobile-more ${!['basecamp','syllabus','focus','life'].includes(page)?'active':''}" data-action="mobile-more" aria-label="More pages" aria-haspopup="dialog"><span aria-hidden="true">⋯</span><span class="mobile-label" aria-hidden="true">More</span></button>`;$('#page-label').textContent=navItems.find(x=>x[0]===page)?.[2]||'Basecamp';$('.avatar-initial').textContent=state.settings.name.charAt(0).toUpperCase();$('#main').innerHTML=({basecamp:home,syllabus,roadmap,life,focus,mocks,rewards,settings,guide}[page]||home)();$('#today-label').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'});bindPage();tick();document.dispatchEvent(new Event('wa:render'));}
function bindPage(){if(page==='focus')$('[name=timer-sound]').onchange=e=>{try{checkEditable();state.settings.timerSound=e.target.checked;persist();if(e.target.checked)prepareAudio();}catch(err){toast(err.message);render();}};if(page==='syllabus'){$('#chapter-search').oninput=e=>{search=e.target.value;const holder=document.createElement('div');holder.innerHTML=syllabus();$('#chapter-results').replaceChildren(...holder.querySelector('#chapter-results').childNodes);$('#chapter-count').textContent=holder.querySelector('#chapter-count').textContent;};$('#status-filter').onchange=e=>{statusFilter=e.target.value;render();};}if(page==='focus'&&!timer){$('[name=focus-subject]').onchange=e=>{focusDraft.subject=e.target.value;focusDraft.chapterId='';render();};$('[name=focus-minutes]').onchange=e=>{focusDraft.custom=e.target.value==='custom';if(!focusDraft.custom)focusDraft.minutes=Number(e.target.value);render();};if($('[name=focus-custom]'))$('[name=focus-custom]').oninput=e=>{focusDraft.minutes=Number(e.target.value);$('#focus-clock').textContent=Number.isInteger(focusDraft.minutes)&&focusDraft.minutes>=1&&focusDraft.minutes<=1440?clockText(focusDraft.minutes*60000):'—:—';};$('[name=focus-chapter]').onchange=e=>{focusDraft.chapterId=e.target.value;};}if(page==='settings')$('#settings-form').onsubmit=e=>{e.preventDefault();try{checkEditable();const f=new FormData(e.currentTarget),next={...state.settings,name:f.get('name').trim(),hours:Number(f.get('hours')),dailyGoal:Number(f.get('dailyGoal')),theme:f.get('theme'),motion:f.has('motion'),sound:f.has('sound'),notes:f.get('notes')};assert(next.name,'Please enter a name.');assert(['jeeDate','clatDate','ailetDate'].every(k=>C.validDate(next[k])),'Enter valid exam dates.');state.settings=next;changed('Preferences saved.');}catch(err){$('#settings-error').textContent=err.message;}};}
function editGuide(id){const holder=document.createElement('div');holder.innerHTML=guideSource();const detail=holder.querySelectorAll('details')[Number(id)];const initial=[...detail.children].filter(x=>x.tagName!=='SUMMARY').map(x=>x.textContent).join('\n\n');modal('Edit field-guide section',area(esc(detail.querySelector('summary').textContent),'text',state.guideEdits?.[id]??initial,'required maxlength="20000"')+actions('Save section'),f=>{checkEditable();state.guideEdits??={};state.guideEdits[id]=f.get('text');changed('Field guide updated.');});}
function editQuest(id){const q=state.quests.find(x=>x.id===id)||{id:uid(),title:'',subject:subjects()[0],date:C.day(),minutes:50,done:false};modal(id?'Edit study block':'Plan a study block',`${field('A concrete task','title',q.title,'text','required maxlength="200" placeholder="Solve 15 quadratic PYQs without notes"')}<div class="form-grid">${select('Subject','subject',subjects(),q.subject)}${field('Planned minutes','minutes',q.minutes,'number','required min="5" max="240"')}${field('Date','date',q.date,'date','required')}</div>${id?button('quest-delete','Delete block',id,'small quiet danger'):''}${actions('Save block')}`,f=>{checkEditable();assert(C.validDate(f.get('date')),'Choose a valid date.');assert(f.get('title').trim(),'Give the block a concrete task.');Object.assign(q,{title:f.get('title').trim(),subject:f.get('subject'),date:f.get('date'),minutes:Number(f.get('minutes'))});if(!id)state.quests.push(q);changed('Study block saved.');});}
function editChapter(id){const c=state.chapters.find(x=>x.id===id)||{id:uid(),name:'',subject:subjects()[0],priority:'Core',prerequisite:'',notes:'',status:'not-started',checks:[],nextReview:''};modal(id?c.name:'Add a chapter',`${field('Chapter / skill name','name',c.name,'text','required maxlength="200"')}<div class="form-grid">${select('Subject','subject',subjects(),c.subject)}${select('Priority','priority',['Foundation','Core','Build next','Later','Conditional','Daily'],c.priority)}${select('Stage','status',Object.entries(statusNames),c.status)}${field('Next revision','nextReview',c.nextReview,'date')}</div>${field('Prerequisites','prerequisite',c.prerequisite,'text','maxlength="10000"')}${area('Study notes and next action','notes',c.notes,'maxlength="10000"')}<div class="notice tiny">Mastery: two most recent checks must each have ≥10 questions and ≥75% correct. A weak new check returns a mastered chapter to revision.</div>${c.checks.length?`<div class="pill-row mb">${c.checks.slice(-4).map(t=>`<span class="tag">${dateLabel(t.date)} · ${t.correct}/${t.total}</span>`).join('')}</div>`:''}${id?`<div class="row-actions">${button('chapter-check','+ Log practice check',id)}${button('chapter-focus','Focus on this',id)}${button('chapter-delete','Delete',id,'small quiet danger')}</div>`:''}${actions()}`,f=>{checkEditable();const nextStatus=f.get('status');assert(f.get('name').trim(),'Enter a chapter name.');assert(nextStatus!=='mastered'||C.canMaster(c),'Log two checks of at least 10 questions, each at 75%+, before marking mastery.');assert(!f.get('nextReview')||C.validDate(f.get('nextReview')),'Choose a valid revision date.');const before=C.totalXP(state);Object.assign(c,{name:f.get('name').trim(),subject:f.get('subject'),priority:f.get('priority'),status:nextStatus,prerequisite:f.get('prerequisite'),notes:f.get('notes'),nextReview:f.get('nextReview')});if(!id)state.chapters.push(c);const earned=nextStatus==='mastered'?C.award(state,'master-'+c.id,40,'mastery'):0;changed(`Chapter saved.${earned?' +40 XP for mastery.':''}`,before);});}
function chapterCheck(id){const c=state.chapters.find(x=>x.id===id);modal('Log an independent practice check',`<p class="muted">${esc(c.name)} · fresh questions, without notes.</p><div class="form-grid">${field('Questions attempted','total',15,'number','required min="1" max="300"')}${field('Correct answers','correct','','number','required min="0" max="300"')}</div>${field('Next revision','nextReview',C.addDays(C.day(),2),'date','required')}<p class="helper">A check needs at least 10 questions to count toward mastery. The two latest checks must each reach 75%.</p>${actions('Save practice check')}`,f=>{checkEditable();const total=Number(f.get('total')),correct=Number(f.get('correct'));assert(Number.isInteger(total)&&Number.isInteger(correct)&&correct<=total,'Correct answers must be a whole number no greater than attempted questions.');assert(C.validDate(f.get('nextReview')),'Choose a valid revision date.');c.checks.push({date:C.day(),total,correct});c.nextReview=f.get('nextReview');if(c.status==='not-started'||c.status==='learning')c.status='practice';if(c.status==='mastered'&&!C.canMaster(c))c.status='revision';changed(C.canMaster(c)?'Two strong checks! You can now mark this chapter mastered.':'Check saved. Repair errors before the next check.');});}
function editWeek(id){const w=state.weeks.find(x=>x.id===id)||{id:uid(),start:C.day(),end:C.addDays(C.day(),6),title:'',physics:'',chemistry:'',maths:'',note:'',blocks:{}};const names=w.blocks?Object.keys(w.blocks).concat(subjects().filter(s=>!Object.hasOwn(w.blocks,s))):subjects();modal(id?'Adjust this week':'Add a planning week',`${field('Week title','title',w.title,'text','required maxlength="200"')}<div class="form-grid">${field('Start','start',w.start,'date','required')}${field('End','end',w.end,'date','required')}</div>${names.map((subject,i)=>area(esc(subject),'block-'+i,w.blocks?.[subject]??w[{Physics:'physics',Chemistry:'chemistry',Maths:'maths'}[subject]]??'','maxlength="10000"')).join('')}${area('Tests and workload notes','note',w.note,'maxlength="10000"')}${id?button('week-delete','Delete week',id,'small quiet danger'):''}${actions('Save week')}`,f=>{checkEditable();assert(C.validDate(f.get('start'))&&C.validDate(f.get('end'))&&f.get('end')>=f.get('start'),'End date must be on or after the start.');for(const k of ['title','start','end','note'])w[k]=f.get(k);w.blocks=Object.fromEntries(names.map((subject,i)=>[subject,f.get('block-'+i)]));if(!id)state.weeks.push(w);changed('Roadmap updated.');});}

function timerElapsed(){return timer?Math.min(timer.minutes*60000,timer.elapsed+(timer.running?Math.max(0,Date.now()-timer.since):0)):0;}
function remaining(){return timer?Math.max(0,timer.minutes*60000-timerElapsed()):0;}
function clockText(ms){const sec=Math.ceil(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function pauseTimer(){if(timer){timer.elapsed=timerElapsed();timer.running=false;timer.since=null;saveTimer();}}
function startTimer(){checkEditable();assert(!timer,'A session is already open.');assert(Number.isInteger(focusDraft.minutes)&&focusDraft.minutes>=1&&focusDraft.minutes<=1440,'Choose a whole number from 1 to 1440 minutes.');if(state.settings.timerSound!==false)prepareAudio();timer={id:uid(),subject:focusDraft.subject,chapterId:focusDraft.chapterId,minutes:focusDraft.minutes,elapsed:0,running:true,since:Date.now(),date:C.day()};saveTimer();render();}
function tick(){document.body.classList.toggle('timer-docked',Boolean(timer)&&page!=='focus');if(stale)return;if(timer){if(timer.running&&remaining()<=0){pauseTimer();render();toast('Session complete. Confirm your actual focus time to collect XP.');chime(true);}const text=clockText(remaining()),clock=$('#focus-clock');if(clock&&clock.textContent!==text)clock.textContent=text;const dock=$('#timer-dock');dock.hidden=page==='focus';if(!dock.hidden){const html=`◷ ${text} · ${remaining()<=0?'Complete':timer.running?'Focusing':'Paused'} ${button('start-focus','Return')}`;if(dock.innerHTML!==html)dock.innerHTML=html;}}else $('#timer-dock').hidden=true;if(C.day()!==lastDay){lastDay=C.day();if($('#daily-quote'))$('#daily-quote').textContent=X.dailyQuote(lastDay);if(!$('#modal').open&&!$('#tutorial').open)render();}}
function logSession(fromTimer=false){if(fromTimer)pauseTimer();const elapsed=fromTimer?Math.floor(timerElapsed()/60000):50;if(fromTimer&&elapsed<1){toast('Less than a minute recorded. Resume or discard this session.');render();return;}const subject=fromTimer?timer.subject:subjects()[0],max=fromTimer?Math.max(1,elapsed):120;modal(fromTimer?'Session complete · collect your progress':'Log work done off-screen',`<p class="muted">${fromTimer?'Confirm the minutes you actually studied. Pauses and interruptions do not count.':'Log an honest session from your notebook, library or coaching work. Do not log timer sessions twice.'}</p><div class="form-grid">${select('Subject','subject',subjects(),subject)}${field('Active minutes','minutes',elapsed,'number',`required min="1" max="${max}"`) }${field('Study date','date',C.day(),'date',`required max="${C.day()}"`)}</div>${area('What did you work on?','note','','required maxlength="2000" placeholder="Solved 18 electrostatics PYQs; revisit potential vs field."')}<p class="helper">Minimum 10 minutes for XP. Today’s focus XP is capped at 360. Backdated sessions fill history without awarding XP.</p>${actions('Save session')}`,f=>{checkEditable();const mins=Number(f.get('minutes')),date=f.get('date');assert(Number.isInteger(mins)&&mins>=1&&mins<=max,'Enter actual whole minutes within the session limit.');assert(C.validDate(date)&&date<=C.day(),'Study date cannot be in the future.');assert(f.get('note').trim(),'Write a short record of the work.');const id=fromTimer?timer.id:uid(),before=C.totalXP(state);assert(!state.sessions.some(s=>s.id===id),'This session was already logged.');state.sessions.push({id,subject:f.get('subject'),minutes:mins,date,note:f.get('note').trim(),chapterId:fromTimer?timer.chapterId:''});const earned=mins>=10&&date===C.day()?C.award(state,'focus-'+id,mins,'focus'):0;if(fromTimer){timer=null;saveTimer();}changed(`Session saved. +${earned} XP. Take a normal break.`,before);});}
function editMock(id){const m=state.mocks.find(x=>x.id===id)||{id:uid(),exam:mockFilter,name:'',date:C.day(),score:0,minutes:mockFilter==='JEE'?180:120,scores:[null,null,null],analysis:'',analysed:false};modal(id?'Review this mock':'Record a real mock',`<div class="form-grid">${select('Exam','exam',Object.keys(examScales()),m.exam)}${field('Date','date',m.date,'date',`required max="${C.day()}"`)}</div>${field('Paper / test series name','name',m.name,'text','required maxlength="150"')}<div class="form-grid">${field('Total score','score',m.score,'number',`required min="${-examScales()[m.exam]/4}" max="${examScales()[m.exam]}" step="0.25"`)}${field('Minutes taken','minutes',m.minutes,'number','required min="1" max="300"')}</div><p class="helper mb">${esc(examList().map(e=>e.name+' /'+e.maxScore).join(' · '))}. Compare tests of similar difficulty.</p><div id="pcm-fields" ${m.exam!=='JEE'?'hidden':''}><div class="form-grid">${field('Physics (optional)','p',m.scores[0]??'','number','min="-25" max="100" step="1"')}${field('Chemistry (optional)','c',m.scores[1]??'','number','min="-25" max="100" step="1"')}${field('Maths (optional)','m',m.scores[2]??'','number','min="-25" max="100" step="1"')}</div></div>${area('Analysis: what lost marks, and what will you repair?','analysis',m.analysis,'maxlength="10000" placeholder="Name the errors and a concrete repair action. Minimum 20 characters to mark analysed."')}<label class="check-label"><input name="analysed" type="checkbox" ${m.analysed?'checked':''}>I reattempted errors and identified repair actions</label>${id?button('mock-delete','Delete record',id,'small quiet danger'):''}${actions('Save mock')}`,f=>{checkEditable();const exam=f.get('exam'),score=Number(f.get('score')),analysed=f.has('analysed'),analysis=f.get('analysis').trim(),scores=exam==='JEE'?['p','c','m'].map(k=>f.get(k)===''?null:Number(f.get(k))):[null,null,null];assert(score>=-examScales()[exam]/4&&score<=examScales()[exam],`Score must fit the ${exam} scale.`);assert(C.validDate(f.get('date'))&&f.get('date')<=C.day(),'Choose a valid past or present date.');assert(!analysed||analysis.length>=20,'Write at least 20 characters describing errors and concrete repairs before marking analysed.');assert(!scores.every(x=>x!==null)||Math.abs(scores.reduce((a,b)=>a+b,0)-score)<.001,'Physics + Chemistry + Maths must equal your total score.');const before=C.totalXP(state);Object.assign(m,{exam,name:f.get('name').trim(),date:f.get('date'),score,minutes:Number(f.get('minutes')),scores,analysis,analysed});if(!id)state.mocks.push(m);let earned=!id?C.award(state,'mock-'+m.id,20,'mock'):0;if(analysed)earned+=C.award(state,'analysis-'+m.id,40,'analysis');mockFilter=exam;changed(`Mock saved. +${earned} XP.${analysed?' Add recurring mistakes to the repair queue.':''}`,before);});$('[name=exam]').onchange=e=>{$('#pcm-fields').hidden=e.target.value!=='JEE';$('[name=score]').max=examScales()[e.target.value];$('[name=score]').min=-examScales()[e.target.value]/4;};}
function editError(id){const e=state.errors.find(x=>x.id===id)||{id:uid(),subject:subjects()[0],topic:'',cause:'Concept',repair:'',nextReview:C.addDays(C.day(),2),reviews:[]};modal(id?'Edit a repair':'Turn a mistake into a repair',`${field('Topic / question reference','topic',e.topic,'text','required maxlength="200"')}<div class="form-grid">${select('Subject','subject',subjects(),e.subject)}${select('Main cause','cause',['Concept','Recall','Calculation','Misreading','Question selection','Time pressure'],e.cause)}</div>${area('Specific repair action','repair',e.repair,'required maxlength="3000" placeholder="Relearn field vs potential, then solve 5 fresh questions without notes."')}${field('Next reattempt','nextReview',e.nextReview,'date','required')}${id?button('error-delete','Delete entry',id,'small quiet danger'):''}${actions('Save repair')}`,f=>{checkEditable();assert(C.validDate(f.get('nextReview')),'Choose a valid date.');assert(f.get('repair').trim().length>=10,'Write a specific repair action (at least 10 characters).');for(const k of ['topic','subject','cause','repair','nextReview'])e[k]=f.get(k).trim();if(!id)state.errors.push(e);changed('Repair saved. Come back and solve it without the solution.');});}
function reviewError(id){const e=state.errors.find(x=>x.id===id);modal('Reattempt complete?',`<p><strong>${esc(e.topic)}</strong></p><p class="muted">${esc(e.repair)}</p>${select('What happened?','result',[['solid','Solved independently'],['again','Still needs work']],'solid')}<p class="helper">Independent solves are spaced to 7, then 21 days. If still shaky, return in 2 days.</p>${actions('Record reattempt')}`,f=>{checkEditable();assert(!e.reviews.includes(C.day()),'This entry already has a reattempt today.');const before=C.totalXP(state);e.reviews.push(C.day());e.nextReview=C.addDays(C.day(),f.get('result')==='again'?2:e.reviews.length===1?7:21);const xp=C.award(state,'review-'+id+'-'+C.day(),5,'review');changed(`Reattempt recorded. +${xp} XP. Next review ${dateLabel(e.nextReview)}.`,before);});}
function editReward(id){const r=state.rewards.find(x=>x.id===id)||{id:uid(),name:'',description:'',cost:40,icon:'✧'};modal(id?'Edit reward':'Add an optional extra',`${field('Reward name','name',r.name,'text','required maxlength="150"')}${area('What you’ll enjoy','description',r.description,'required maxlength="1000"')}${field('Crystal cost','cost',r.cost,'number','required min="10" max="10000"')}<p class="helper">20 crystals is roughly four 50-minute sessions. Keep food, sleep and normal rest outside the reward system.</p>${id?button('reward-delete','Delete reward',id,'small quiet danger'):''}${actions('Save reward')}`,f=>{checkEditable();Object.assign(r,{name:f.get('name').trim(),description:f.get('description').trim(),cost:Number(f.get('cost'))});if(!id)state.rewards.push(r);changed('Reward saved.');});}
function redeem(id){const r=state.rewards.find(x=>x.id===id);modal('You earned a little extra',`<div class="reward-icon">${esc(r.icon)}</div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.description)}</p><p>Spend <strong>${r.cost} crystals</strong>? Your balance will be ${C.crystals(state)-r.cost}. Your level stays the same.</p>${actions('Redeem reward')}`,()=>{checkEditable();assert(C.crystals(state)>=r.cost,'Not enough crystals yet.');state.redemptions.push({id:uid(),name:r.name,cost:r.cost,date:C.day(),used:false});changed('Reward added to your shelf. Enjoy it deliberately.');});}
function deleteRecord(kind,id){const map={quest:'quests',chapter:'chapters',week:'weeks',mock:'mocks',error:'errors',reward:'rewards'},key=map[kind];modal('Remove this record?',`<p class="muted">This removes the ${kind} from your planner. Existing XP and redeemed rewards stay in your history. Export a backup first if you may need the record later.</p>${actions('Remove record')}`,()=>{checkEditable();state[key]=state[key].filter(x=>x.id!==id);changed('Record removed.');});}
function download(data,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportState(){download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'winter-arc-'+C.day()+'.json');toast('Backup downloaded. Keep it somewhere safe.');}
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{assert(file.size<4*1024*1024,'Backup must be smaller than 4 MB.');const incoming=C.validate(disk.decode(await file.text()).planner);modal('Restore this backup?',`<p>This replaces the current planner with <strong>${esc(incoming.settings.name)}’s</strong> backup.</p><p class="muted">${incoming.sessions.length} focus sessions · ${incoming.mocks.length} mocks · ${incoming.chapters.length} chapters · ${C.totalXP(incoming)} XP.</p><p>Export your current progress first if you want to keep both versions.</p><div class="row-actions">${button('export','Export current progress')}</div>${actions('Replace with backup')}`,()=>{assert(!stale,'Reload this tab before restoring.');const mode=disk.handle?'file':state.settings.storageMode==='file'&&disk.supported?'file':'browser';state=clone(incoming);state.settings.storageMode=mode;loadError=false;timer=null;saveTimer();changed('Backup restored.');$('#storage-warning')?.remove();});}catch(err){toast(err.message||'Invalid backup. Nothing changed.');}};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.page){go(el.dataset.page);return;}if(el.dataset.subject){subjectFilter=el.dataset.subject;render();return;}if(el.dataset.exam){mockFilter=el.dataset.exam;render();return;}const a=el.dataset.action,id=el.dataset.id;if(!a)return;try{
if(a==='syllabus-upload'){checkEditable();$('#syllabus-file').click();return;}if(a==='mobile-more'){showMobileMenu();return;}if(a==='close'){closeModal();return;}if(a==='celebration-close'){$('#celebration').close();return;}if(a==='export'){exportState();return;}if(a==='export-raw'){download(localStorage.getItem(KEY)||'{}','winter-arc-recovery.json');return;}if(a==='import'){$('#import-file').click();return;}
if(['settings','syllabus','mocks'].includes(a)){go(a);return;}if(a==='start-focus'){go('focus');return;}if(a==='zen'){document.body.classList.toggle('focus-only');render();return;}
if(a==='theme'){checkEditable();state.settings.theme=state.settings.theme==='dark'?'light':'dark';persist();applyTheme();return;}
if(a==='file-open'){connectFile(false);return;}if(a==='file-reconnect'){reconnectFile();return;}if(a==='file-save'){saveToDisk();return;}if(a==='tutorial'){startTutorial();return;}if(a==='tutorial-next'){tourStep(1);return;}if(a==='tutorial-back'){tourStep(-1);return;}if(a==='tutorial-skip'||a==='tutorial-finish'){endTutorial();return;}
checkEditable();
if(a==='suggest')suggestQuests();else if(a==='quest-new')editQuest();else if(a==='quest-edit')editQuest(id);else if(a==='quest-toggle'){const q=state.quests.find(x=>x.id===id),before=C.totalXP(state);q.done=!q.done;const xp=q.done?C.award(state,'quest-'+id,10,'quest'):0;changed(q.done?`Study block complete. +${xp} XP.`:'Block reopened. Its XP cannot be earned twice.',before);if(q.done)document.dispatchEvent(new CustomEvent('wa:completed',{detail:{id}}));}
else if(a==='workout-new')logWorkout();else if(a==='goal-new')editWeeklyGoal();else if(a==='goal-edit')editWeeklyGoal(id);else if(a==='goal-progress')logGoalProgress(id);else if(a==='goal-claim')claimWeeklyGoal(id);else if(a==='goal-reward'){checkEditable();const g=state.weeklyGoals.find(g=>g.id===id);assert(g?.claimed,'Complete and claim the goal first.');g.rewardUsed=true;changed('Weekly reward enjoyed.');}else if(a==='workspace')editWorkspace();else if(a==='bulk-chapters')bulkChapters();else if(a==='companions')chooseCompanion();else if(a==='companion-evolution')showEvolution();else if(a==='companion-pick'){checkEditable();state.settings.companion=id;changed('Companion selected.');}else if(a==='file-create')connectFile(true);else if(a==='file-open')connectFile(false);else if(a==='file-reconnect')reconnectFile();else if(a==='file-save')saveToDisk();else if(a==='tutorial')startTutorial();else if(a==='tutorial-next')tourStep(1);else if(a==='tutorial-back')tourStep(-1);else if(a==='tutorial-skip'||a==='tutorial-finish')endTutorial();else if(a==='welcome')welcome();else if(a==='chapter-new')editChapter();else if(a==='chapter')editChapter(id);else if(a==='chapter-check')chapterCheck(id);else if(a==='chapter-focus'){const c=state.chapters.find(x=>x.id===id);assert(!timer,'Finish or discard the current focus session first.');focusDraft.subject=c.subject;focusDraft.chapterId=id;closeModal();go('focus');}
else if(a==='guide-edit')editGuide(id);else if(a==='week-new')editWeek();else if(a==='week-edit')editWeek(id);else if(a==='timer-test-sound'){if(state.settings.timerSound===false)toast('Enable Completion chime to preview it.');else chime(true);}else if(a==='timer-start')startTimer();else if(a==='timer-toggle'){if(timer.running)pauseTimer();else{if(remaining()<=0)return;if(state.settings.timerSound!==false)prepareAudio();timer.running=true;timer.since=Date.now();saveTimer();}render();}else if(a==='timer-finish')logSession(true);else if(a==='timer-discard'){modal('Discard this session?',`<p class="muted">The timer has ${Math.floor(timerElapsed()/60000)} active minutes. Discarding gives no XP and removes this timer.</p>${actions('Discard timer')}`,()=>{timer=null;saveTimer();closeModal();render();});}else if(a==='session-new')logSession();
else if(a==='mock-new')editMock();else if(a==='mock-edit')editMock(id);else if(a==='error-new')editError();else if(a==='error-edit')editError(id);else if(a==='error-review')reviewError(id);else if(a==='reward-new')editReward();else if(a==='reward-edit')editReward(id);else if(a==='redeem')redeem(id);else if(a==='reward-use'){state.redemptions.find(x=>x.id===id).used=true;changed('Enjoyed. Now carry the good energy forward.');}else if(a.endsWith('-delete'))deleteRecord(a.split('-')[0],id);
}catch(err){toast(err.message||'Something went wrong. Your existing saved progress is still available.');}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(navItems.some(n=>n[0]===p)&&p!==page){page=p;render();}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){stale=true;if(timer){timer.elapsed=timerElapsed();timer.running=false;}warning('Progress changed in another tab. Reload this tab to sync before editing.');}});
window.addEventListener('pagehide',()=>{if(!stale)saveTimer();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const themeButton=document.createElement('button');themeButton.id='theme-toggle';themeButton.className='icon-button';themeButton.dataset.action='theme';$('.top-tools').insertBefore(themeButton,$('.top-tools').firstChild);
// Ambient snowfall is managed by motion.js.
boot();
function showInitial(){document.body.classList.toggle('test-mode',TEST);render();if(TEST)warning('TEST SANDBOX — separate storage. These actions do not change your real planner.');if(loadError)warning('Existing progress could not be read, or browser storage is blocked. Data has not been overwritten. Open Settings to export recovery data or restore a backup.');else if(timer)toast('Your previous timer was recovered paused. Resume when ready.');}
setInterval(tick,1000);setInterval(()=>{if(timer?.running&&!stale)saveTimer();},5000);
/* Optional browser-standard read access; no AI integration or external requests. */
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'winter_arc_read_progress',title:'Read Winter Arc progress',description:'Read the visible local study summary without modifying progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No input fields are accepted.');return {focusToday:C.focusMinutes(state,C.day()),level:C.level(C.totalXP(state)),xp:C.totalXP(state),crystals:C.crystals(state),topicsMastered:state.chapters.filter(c=>c.subject!=='Law'&&c.status==='mastered').length,mocksRecorded:state.mocks.length};}})).catch(()=>{});}catch{}}

/* Reuse the same routes and dialogs for a thumb-friendly mobile menu. */
function showMobileMenu(){modal('Your basecamp',`<p class="muted">${esc(state.settings.name)} · ${esc($('#save-status').textContent)}</p><div class="mobile-menu">${navItems.map(([id,icon,name])=>`<button type="button" data-page="${id}" ${id===page?'aria-current="page"':''}><span aria-hidden="true">${icon}</span><span>${name}</span><span aria-hidden="true">›</span></button>`).join('')}</div><div class="row-actions mt">${button('export','Download backup','','primary')}${button('close','Close menu')}</div>`,()=>{});}
// Keep the on-screen keyboard from competing with fixed controls.
let restingViewportHeight=window.visualViewport?.height||innerHeight;
function fitKeyboard(){const view=window.visualViewport,height=view?.height||innerHeight;document.documentElement.style.setProperty('--visible-height',height+'px');const editing=document.activeElement?.matches('input,textarea,select,[contenteditable="true"]');if(!editing)restingViewportHeight=height;document.body.classList.toggle('keyboard-open',Boolean(editing&&restingViewportHeight-height>150));}
window.visualViewport?.addEventListener('resize',fitKeyboard);
document.addEventListener('focusin',fitKeyboard);
document.addEventListener('focusout',()=>requestAnimationFrame(fitKeyboard));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
fitKeyboard();
